self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((cache) => cache.addAll(FILES.map((f) => new Request(new URL(f, self.registration.scope), { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('hamesh-dakot-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  const navigation = request.mode === 'navigate';
  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      // Pages carry options in the query (?day=3, ?next=1); the cached page is the same file.
      const cached = await cache.match(request, { ignoreSearch: navigation });
      if (cached) return cached;
      try {
        return await fetch(request);
      } catch (err) {
        // Offline at an address the site doesn't have: send the visitor to the hub (a redirect,
        // not the hub's HTML, so its relative links resolve from the right folder).
        if (navigation) return Response.redirect(new URL('./', self.registration.scope), 302);
        throw err;
      }
    }),
  );
});
